input.command:
cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Simplest case ---
  it.todo("quotes an empty item list as 5 G (processing fee only)");

  // --- Base premiums per main item type (plain item, newcomer with 0 years, first item) ---
  it.todo("quotes a plain sword with base premium 100 G");
  it.todo("quotes a plain amulet with base premium 60 G");
  it.todo("quotes a plain staff with base premium 80 G");
  it.todo("quotes a plain potion with base premium 40 G");

  // --- Component base premiums and the building block of 3 alike components ---
  it.todo("quotes 1 rune with base premium 25 G");
  it.todo("quotes 2 runes with base premium 50 G (no block)");
  it.todo("quotes 3 runes with base premium 60 G (block applies)");
  it.todo("quotes 4 runes with base premium 100 G (no block -- block requires exactly 3)");
  it.todo("quotes 7 runes with base premium 175 G (no block -- block requires exactly 3)");
  it.todo("quotes 1 moonstone with base premium 25 G");
  it.todo("quotes 2 runes + 1 moonstone with base premium 75 G (no block: alike means same type)");
  it.todo("quotes 3 runes + 3 moonstones with base premium 120 G (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge to a cursed item's base premium (cursed sword -> 150 G base+curse)");
  it.todo("adds a 30 % high-enchantment surcharge at enchantment exactly 5 (sword -> 130 G base+enchantment)");
  it.todo("adds no high-enchantment surcharge at enchantment 4 (plain sword -> 100 G base)");
  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5 (-> 180 G)");

  // --- Policy-wide modifiers ---
  it.todo("applies a 20 % loyalty discount at exactly 2 years with MHPCO (sword -> 80 G after discount)");
  it.todo("applies no loyalty discount at 1 year with MHPCO (sword -> 100 G)");
  it.todo("applies a 10 % first-insurance surcharge per item in the quote (sword -> 110 G)");
  it.todo("applies a 15 % follow-up discount to every contract after the customer's first quote (second quote of a sword -> 95 G before fee)");
  it.todo("adds the 5 G processing fee at the very end of every quote");

  // --- Modifier scope on multi-item policies ---
  it.todo("applies the curse surcharge only to the cursed item's base premium on a multi-item policy (cursed sword + plain amulet -> 210 G before further modifiers and fee)");

  // --- Rounding in the MHPCO's favour ---
  it.todo("rounds a premium of 197.5 G up to 198 G");
  it.todo("rounds a payout of 350.5 G down to 350 G");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Integration examples ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3, 0 years, no previous contract) as 165 G");
  it.todo("quotes a long-standing customer's second contract for a cursed steel sword (enchantment 7, 3 years) as 160 G");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("pays out 400 G for a steel sword with enchantment 3 damaged by 500 G (full reimbursement minus 100 G deductible)");
  it.todo("pays out 100 G for a rune (no enchantment, no material) damaged by 200 G");
  it.todo("applies the 100 G deductible once per damaged item (sword 500 G + amulet 300 G -> payout 600 G)");

  // --- Claim: special clauses ---
  it.todo("reimburses 50 % for damage to an item with enchantment exactly 8 before the deductible (dragon sword, damage 1000 G -> payout 400 G)");
  it.todo("reimburses steel sword with enchantment 9 damaged by 1000 G at 50 % then deductible -> payout 400 G");
  it.todo("reimburses dragon-material sword with enchantment 5 damaged by 800 G in full then deductible -> payout 700 G");
  it.todo("lets the 50 % high-enchantment rule win over full dragon reimbursement (dragon sword, enchantment 9, damage 1000 G -> payout 400 G)");

  // --- Claim: insurance sum and cap ---
  it.todo("caps a policy at twice the insurance sum (sword + amulet -> insurance sum 1600 G, cap 3200 G)");
  it.todo("bases the cap on unmodified insurance values (cursed sword, premium 165 G -> cap 2000 G)");
  it.todo("includes component insurance values in the insurance sum unaffected by the block discount (sword + 3 runes -> insurance sum 1750 G, cap 3500 G)");
  it.todo("reports the remaining cap after a claim (sword, cap 2000 G, claim 1500 G -> payout 1400 G, remainingCap 600 G)");
  it.todo("reduces a later payout to the remaining cap (second claim of 1500 G -> payout 600 G, remainingCap 0 G)");

  // --- Multiple items of the same type ---
  it.todo("sums insurance values for two swords in one policy (insurance sum 2000 G, cap 4000 G)");
  it.todo("treats two damage entries of the same item type as separate damages each with its own deductible");

  // --- Error cases (observable contract: the CLI exits non-zero and writes an error description to stderr; the domain layer signals this by throwing an Error) ---
  it.todo("rejects a quote containing an item with an unknown type (e.g. broomstick) by throwing an Error");
  it.todo("rejects a claim whose damage references an item type not covered by the policy (amulet damaged, only a sword insured) by throwing an Error");
  it.todo("rejects a claim whose damage references an unknown item type by throwing an Error");
  it.todo("rejects a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) by throwing an Error");
  it.todo("rejects a claim containing a damage entry with a negative amount (-200) by throwing an Error");

  // --- CLI adapter ---
  it.todo("CLI reads a scenario from stdin and writes {results:[{premium}]} for a quote step to stdout");
  it.todo("CLI writes {payout, remainingCap} for a claim step referencing an earlier quote step by index");
  it.todo("CLI processes the schema example (amulet quote then 200 G fire claim) producing premium 61 G and payout 100 G with remainingCap 1100 G");
  it.todo("CLI exits with a non-zero status code and writes an error description to stderr for an invalid scenario, writing no results to stdout");
});
EOF
pnpm test 2>&1 | tail -15

