}''','''export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE = 100;
const HALF_REIMBURSEMENT_LEVEL = 8;
const HALF_REIMBURSEMENT_RATE = 0.5;

function roundPayoutInOfficesFavour(payout: number): number {
  return Math.floor(payout);
}

function reimbursementRate(item: Item): number {
  return (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_LEVEL ? HALF_REIMBURSEMENT_RATE : 1;
}

function payoutForDamage(item: Item, amount: number): number {
  return amount * reimbursementRate(item) - DEDUCTIBLE;
}

export class ClaimOffice {
  private contracts = 0;
  private readonly policies: Item[][] = [];

  constructor(private readonly customer: Customer) {}

  quote(items: Item[]): number {
    const premium = premiumFor(this.customer, items, this.contracts);
    this.contracts += 1;
    this.policies.push(items);
    return premium;
  }

  claim(policy: number, incident: Incident): ClaimResult {
    const items = this.policies[policy];
    const payout = incident.damages.reduce((total, damage) => {
      const item = items.find((candidate) => candidate.type === damage.itemType) as Item;
      return total + payoutForDamage(item, damage.amount);
    }, 0);
    return { payout: roundPayoutInOfficesFavour(payout), remainingCap: 0 };
  }
}''')
